sqlGroup.select:
select a.id, b.name as contactName, a.contact_id as contactId, a.`name`, a.item, a.category, a.amount, a.remark, a.invites, date_format(a.created_time,'%Y-%m-%d %H:%i:%s') as created_time, a.tax, a.untaxed_amount, a.img1, a.img2, CONCAT_WS( ";", a.img1, a.img2) AS img, date_format(a.occur_date,'%Y-%m-%d') as occur_date, a.submit_status from jml_reimbursement_detail a left join jml_contact b ON a.contact_id = b.id
a.reimbursement_id =#{reimId}
order by a.created_time desc
